        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52700.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { if (typeof scwin.adjReqPop === 'function') { scwin.adjReqPop(r["follwBzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.adjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.adjReqPop'); } return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { if (typeof scwin.editStatus === 'function') { await scwin.editStatus(r["follwBzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.editStatus (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.editStatus'); } return; } return; } if (r["listProcsStatCd"] === '') { if (typeof scwin.viewDetail === 'function') { scwin.viewDetail(r["bzProcsNo"], "1"); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '30') { if (typeof scwin.viewDetail === 'function') { scwin.viewDetail(r["bzProcsNo"], "2"); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '35') { if (typeof scwin.viewDetail === 'function') { scwin.viewDetail(r["bzProcsNo"], "2"); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '37') { if (typeof scwin.viewDetail === 'function') { scwin.viewDetail(r["bzProcsNo"], "2"); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (typeof scwin.viewDetail === 'function') { scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ())'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};


