 * @name scwin.grd_pageList_fmt_column2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "stkcertListDd") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: column2 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_pageList_fmt_listProcsStatNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fmt_listProcsStatNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (v === '') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "listProcsStatNm") : '') ?? '') + '</a>'; }
        if (v === '30') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "작성중" + '</a>'; }
        if (v === '35') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정가능" + '</a>'; }
        if (v === '37') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "재작성" + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "listProcsStatNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.listProcsStatNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_pageList_fmt_column7
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (['33','36'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column7" }); return String(data ?? ''); }
};

/**
 * @event
 * @name scwin.grd_pageList_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' });
    }
};

/**
